python3 - <<'PY'
import lgpio, time
PHYS={2:3,3:5,4:7,17:11,27:13,22:15,10:19,9:21,11:23,5:29,6:31,13:33,19:35,26:37,18:12,23:16,24:18,25:22,8:24,7:26,12:32,16:36,20:38,21:40,15:10}
MIN_LOW=0.005
h=lgpio.gpiochip_open(0); pins=sorted(PHYS)
for p in pins: lgpio.gpio_claim_input(h,p,lgpio.SET_PULL_UP)
time.sleep(0.1)
last={p:lgpio.gpio_read(h,p) for p in pins}; fell={}
print("START filtered (lows >=5ms only). idle LOW:",[f"pin{PHYS[p]}" for p in pins if last[p]==0],flush=True)
t0=time.time(); glitch={}
while time.time()-t0<600:
    now=time.time()
    for p in pins:
        v=lgpio.gpio_read(h,p)
        if v!=last[p]:
            if v==0: fell[p]=now
            else:
                d=now-fell.pop(p,now)
                if d>=MIN_LOW: print(f"{now-t0:8.3f}s GPIO{p} (physical pin {PHYS[p]}) LOW for {1000*d:.0f}ms",flush=True)
                else: glitch[p]=glitch.get(p,0)+1
            last[p]=v
    for p,tf in list(fell.items()):
        if now-tf>2 and last[p]==0: print(f"{now-t0:8.3f}s GPIO{p} (physical pin {PHYS[p]}) held LOW",flush=True); fell[p]=now+1e9
    time.sleep(0.0005)
print("END glitches(<5ms) per pin:",{f"pin{PHYS[p]}":n for p,n in glitch.items()},flush=True)
PY
EOF

