{
  "name": "@takarabako/backend",
  "version": "0.1.0",
  "private": true,
  "description": "Takarabako backend/orchestrator — PRD §7.3. Treasury signer, deposit/verify/withdraw API, kiosk-facing endpoints.",
  "type": "module",
  "scripts": {
    "dev": "tsx watch --env-file=.env src/index.ts",
    "build": "tsc -p tsconfig.json",
    "start": "node dist/index.js",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@anthropic-ai/sdk": "^0.125.0",
    "@privy-io/node": "^0.34.0",
    "express": "^4.21.2",
    "viem": "^2.56.3",
    "zod": "^3.23.8"
  },
  "devDependencies": {
    "@types/express": "^4.17.21",
    "@types/node": "^22.10.0",
    "tsx": "^4.19.2",
    "typescript": "^5.7.2"
  }
}
{
  "compilerOptions": {
    "target": "ES2022",
    "module": "NodeNext",
    "moduleResolution": "NodeNext",
    "outDir": "dist",
    "rootDir": "src",
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "resolveJsonModule": true,
    "declaration": false
  },
  "include": ["src"]
}
import express from "express";
import { config } from "./config.js";
import { verifyRouter } from "./routes/verify.js";
import { depositRouter } from "./routes/deposit.js";
import { agentRouter } from "./routes/agentRoutes.js";
import { withdrawRouter } from "./routes/withdraw.js";
import { positionRouter } from "./routes/position.js";

const app = express();
app.use(express.json());

// Dev-only convenience: the kiosk page (device-agent) fetches this API
// directly from the browser. Lock this down (or put both behind one origin)
// before this ever leaves a hackathon table.
app.use((_req, res, next) => {
  res.header("Access-Control-Allow-Origin", "*");
  res.header("Access-Control-Allow-Headers", "Content-Type");
  res.header("Access-Control-Allow-Methods", "GET,POST");
  next();
});

app.get("/health", (_req, res) => res.json({ ok: true }));

app.use(verifyRouter);
app.use(depositRouter);
app.use(agentRouter);
app.use(withdrawRouter);
app.use(positionRouter);

// Catches anything asyncHandler forwards (chain calls, Privy, the agent) —
// without this, an unhandled rejection in an async route takes the whole
// process down instead of just failing that one request.
app.use((err: unknown, _req: express.Request, res: express.Response, _next: express.NextFunction) => {
  console.error(err);
  const message = err instanceof Error ? err.message : "internal error";
  res.status(500).json({ error: message });
});

app.listen(config.port, () => {
  console.log(`takarabako backend listening on :${config.port}`);
});
import { keccak256, toBytes, getAddress } from "viem";

/// In-memory store for the hackathon build. PRD §9 data model.
/// ATM-style flow (§6.1/§6.2 swapped): identity comes first now — /verify
/// creates the Account, /deposit just credits it — so there's no more
/// separate per-box "handle"/"Wallet" concept sitting ahead of identity.
/// One Account per Privy user, keyed by `privyUserId`.
///
/// Phase 1 (done): `depositOnChain`/`withdrawAllOnChain` (chain.ts) read and
/// write real vault state keyed by `Account.boundAddress` below. Still
/// local: the event log and the Uniswap-position records — those move to a
/// small Postgres/SQLite table whenever Phase 3 makes them real.

export type RiskTier = "low" | "medium" | "high";

export interface Account {
  privyUserId: string; // PK — Privy's user id, our sybil-resistance signal (one email -> one Privy user)
  ensName: string;
  boundAddress: string; // deterministic bookkeeping address the treasury moves vault/position funds for
  privyWalletAddress: string; // the user's real embedded wallet (Privy), for reference/future use
  idleBalance: number; // USDC not yet routed into a position
  createdAt: number;
}

export interface Position {
  positionId: number;
  ensName: string;
  user: string; // privyUserId
  riskTier: RiskTier;
  pair: string;
  amount: number; // USDC principal, demo units
  apyBps: number;
  openedAt: number;
  nftTokenId?: string; // real Uniswap v3 position NFT id, once minted (chain.ts)
}

export interface DepositEvent {
  id: string;
  privyUserId: string;
  denomination: number; // face value of the cash, in `currency`
  currency: "USD" | "MYR";
  usdAmount: number; // what the vault was actually credited
  txHash: string;
  ts: number;
}

export interface WithdrawEvent {
  id: string;
  privyUserId: string;
  grossUsdc: number;
  feeBps: number;
  netUsdc: number;
  ts: number;
}

const accountsByPrivyId = new Map<string, Account>();
const positionsByUser = new Map<string, Position[]>();
const depositEvents: DepositEvent[] = [];
const withdrawEvents: WithdrawEvent[] = [];

let nextPositionId = 1;

/// Deterministic address derived from the Privy user id — valid,
/// checksummed, stable across restarts, but not one anyone holds the key
/// to. That's fine: only the treasury ever moves vault shares for it
/// (onlyOwner in TakarabakoVault.sol), so this is purely a bookkeeping key
/// on-chain. The user's own real wallet (Privy) is tracked separately.
export function deriveBoundAddress(privyUserId: string): string {
  return getAddress(`0x${keccak256(toBytes(privyUserId)).slice(-40)}`);
}

export const store = {
  accounts: accountsByPrivyId,

  createAccount(account: Account) {
    accountsByPrivyId.set(account.privyUserId, account);
  },

  getAccount(privyUserId: string): Account | undefined {
    return accountsByPrivyId.get(privyUserId);
  },

  addPosition(position: Omit<Position, "positionId">): Position {
    const full: Position = { ...position, positionId: nextPositionId++ };
    const existing = positionsByUser.get(position.user) ?? [];
    existing.push(full);
    positionsByUser.set(position.user, existing);
    return full;
  },

  getPositions(privyUserId: string): Position[] {
    return positionsByUser.get(privyUserId) ?? [];
  },

  clearPositions(privyUserId: string) {
    positionsByUser.set(privyUserId, []);
  },

  logDeposit(event: DepositEvent) {
    depositEvents.push(event);
  },

  logWithdraw(event: WithdrawEvent) {
    withdrawEvents.push(event);
  },
};
import { Router } from "express";
import { z } from "zod";
import { store, deriveBoundAddress } from "../store.js";
import { getOrCreateUserWallet } from "../privy.js";
import { deriveEnsLabel, walletSubname, registerSubname } from "../ens.js";
import { asyncHandler } from "../asyncHandler.js";

/// POST /verify — PRD §6.1 (ATM-style: identity first, cash second). Takes
/// an email on the kiosk screen, resolves (or creates) that person's real
/// Privy user + embedded wallet server-side, and — for a brand-new
/// account — registers their ENS v2 subname right here, before any cash
/// has been inserted. This is the sybil gate for the whole system (PRD
/// §10): like a real ATM, you identify yourself before the machine knows
/// which account to credit, rather than depositing blind and hoping the
/// right person claims it afterward.
export const verifyRouter = Router();

const VerifyBody = z.object({
  email: z.string().email(),
});

verifyRouter.post("/verify", asyncHandler(async (req, res) => {
  const parsed = VerifyBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: parsed.error.flatten() });
    return;
  }
  const { email } = parsed.data;

  const { userId, walletAddress, fundingTxHash } = await getOrCreateUserWallet(email);

  const existing = store.getAccount(userId);
  if (existing) {
    res.json({
      verified: true,
      userId,
      ensName: existing.ensName,
      boundAddress: existing.boundAddress,
      privyWalletAddress: existing.privyWalletAddress,
      balance: existing.idleBalance,
      reused: true,
    });
    return;
  }

  const boundAddress = deriveBoundAddress(userId);
  const ensName = walletSubname(deriveEnsLabel(email));
  const { txHash: ensTxHash } = await registerSubname(ensName, boundAddress);

  store.createAccount({
    privyUserId: userId,
    ensName,
    boundAddress,
    privyWalletAddress: walletAddress,
    idleBalance: 0,
    createdAt: Date.now(),
  });

  res.json({
    verified: true,
    userId,
    ensName,
    boundAddress,
    privyWalletAddress: walletAddress,
    balance: 0,
    reused: false,
    fundingTxHash,
    ensTxHash,
  });
}));
import type { Request, Response, NextFunction, RequestHandler } from "express";

/// Express 4 doesn't forward a rejected promise from an async handler to
/// its error middleware — it becomes an unhandled rejection and, by
/// default, kills the whole Node process. Every route in this backend is
/// async (chain calls, Privy verification, the agent), so wrap each one
/// with this instead of hand-rolling try/catch per route.
export function asyncHandler(fn: (req: Request, res: Response, next: NextFunction) => Promise<unknown>): RequestHandler {
  return (req, res, next) => {
    fn(req, res, next).catch(next);
  };
}

