1	import { keccak256, toBytes, getAddress } from "viem";
2	
3	/// In-memory store for what hasn't moved to Postgres yet: Uniswap position
4	/// records and withdraw events. Accounts, sessions and deposits live in
5	/// Postgres (accounts.ts, sessions.ts), so a restart doesn't forget them.
6	
7	export type RiskTier = "low" | "medium" | "high";
8	
9	export interface Position {
10	  positionId: number;
11	  ensName: string;
12	  user: string; // privyUserId
13	  riskTier: RiskTier;
14	  pair: string;
15	  amount: number; // USDC principal, demo units
16	  apyBps: number;
17	  openedAt: number;
18	  nftTokenId?: string; // real Uniswap v3 position NFT id, once minted (chain.ts)
19	}
20	
21	export interface WithdrawEvent {
22	  id: string;
23	  privyUserId: string;
24	  grossUsdc: number;
25	  feeBps: number;
26	  netUsdc: number;
27	  ts: number;
28	}
29	
30	const positionsByUser = new Map<string, Position[]>();
31	const withdrawEvents: WithdrawEvent[] = [];
32	
33	let nextPositionId = 1;
34	
35	/// Deterministic address derived from the Privy user id — valid,
36	/// checksummed, stable across restarts, but not one anyone holds the key
37	/// to. That's fine: only the treasury ever moves vault shares for it
38	/// (onlyOwner in TakarabakoVault.sol), so this is purely a bookkeeping key
39	/// on-chain. The user's own real wallet (Privy) is tracked separately.
40	export function deriveBoundAddress(privyUserId: string): string {
41	  return getAddress(`0x${keccak256(toBytes(privyUserId)).slice(-40)}`);
42	}
43	
44	export const store = {
45	  addPosition(position: Omit<Position, "positionId">): Position {
46	    const full: Position = { ...position, positionId: nextPositionId++ };
47	    const existing = positionsByUser.get(position.user) ?? [];
48	    existing.push(full);
49	    positionsByUser.set(position.user, existing);
50	    return full;
51	  },
52	
53	  getPositions(privyUserId: string): Position[] {
54	    return positionsByUser.get(privyUserId) ?? [];
55	  },
56	
57	  clearPositions(privyUserId: string) {
58	    positionsByUser.set(privyUserId, []);
59	  },
60	
61	  logWithdraw(event: WithdrawEvent) {
62	    withdrawEvents.push(event);
63	  },
64	};

