28	  const currency = req.query.currency === "MYR" ? "MYR" : "USD";
29	  res.json({ currency, ...(await usdPerUnit(currency)) });
30	}));
31	
32	// Any live session may deposit: email login (full) or wallet-QR login
33	// (deposit). The account comes from the session, never the request body.
34	depositRouter.post("/deposit", requireSession("deposit"), asyncHandler(async (req, res) => {
35	  const parsed = DepositBody.safeParse(req.body);
36	  if (!parsed.success) {
37	    res.status(400).json({ error: parsed.error.flatten() });
38	    return;
39	  }
40	  const { amount, currency } = parsed.data;
41	  const session: Session = res.locals.session;
42	
