44	  if (!account) {
45	    res.status(404).json({ error: "unknown account" });
46	    return;
47	  }
48	  if (!chainReady) {
49	    res.status(503).json({ error: "chain not configured — set TREASURY_PRIVATE_KEY/USDC_ADDRESS/VAULT_ADDRESS in backend/.env" });
50	    return;
51	  }
52	
