57	  await recordDeposit({ privyUserId: account.privyUserId, currency, amount, usdAmount, txHash });
58	
59	  res.json({
60	    ensName: account.ensName,
61	    boundAddress: account.boundAddress,
62	    balance: value,
63	    txHash,
64	    currency,
65	    usdAmount,
66	    fxRate: rate,
67	    fxSource: source,
68	    expiresAt: session.expiresAt,
69	  });
70	}));

